{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  let d = [];
  try {
    await page.setViewport({ width: 1280, height: 800 });
    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'networkidle2', timeout: 25000 });
    d.push('1-page loaded');

    // Verifica se o campo de email existe
    const emailExists = await page.$('#email_principal');
    d.push('2-email field: ' + (emailExists ? 'found' : 'NOT FOUND'));

    if (emailExists) {
      await emailExists.click();
      await emailExists.type(EMAIL, { delay: 15 });
      const emailValue = await page.evaluate(() => document.querySelector('#email_principal')?.value || 'empty');
      d.push('3-email typed: ' + emailValue.substring(0, 10) + '...');
    }
    await w(500);

    // Lista todos os botoes
    const allButtons = await page.evaluate(() => {
      return [...document.querySelectorAll('button')].map(b => b.textContent.trim().substring(0, 30)).join(' | ');
    });
    d.push('4-buttons: ' + allButtons.substring(0, 80));

    // Tenta clicar no botao continuar
    const continuarResult = await page.evaluate(() => {
      const buttons = document.querySelectorAll('button');
      for (const b of buttons) {
        if (b.textContent.includes('Continuar com Email')) {
          b.click();
          return 'clicked: ' + b.textContent.trim().substring(0, 30);
        }
      }
      return 'NOT FOUND';
    });
    d.push('5-continuar: ' + continuarResult);

    // Espera um pouco
    await w(2000);

    // Verifica o que mudou na pagina
    const afterClick = await page.evaluate(() => {
      const pwdField = document.querySelector('#pwdInput');
      const pageText = document.body.innerText.substring(0, 300);
      const allInputs = [...document.querySelectorAll('input')].map(i => i.id || i.type || 'no-id').join(', ');
      return { hasPwd: !!pwdField, inputs: allInputs, text: pageText };
    });
    d.push('6-pwdInput exists: ' + afterClick.hasPwd);
    d.push('7-inputs: ' + afterClick.inputs.substring(0, 60));
    d.push('8-text: ' + afterClick.text.substring(0, 100));

    // Se tem campo de senha, continua
    if (afterClick.hasPwd) {
      const sInp = await page.$('#pwdInput');
      await sInp.click();
      await sInp.type(SENHA, { delay: 15 });
      d.push('9-senha typed');

      await w(500);

      await page.evaluate(() => {
        const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Entrar');
        if(b) b.click();
      });
      d.push('10-entrar clicked');

      await w(3000);
      d.push('11-url: ' + page.url());
    }

    return { success: true, debug: d };
  } catch (error) {
    d.push('ERROR: ' + error.message);
    return { success: false, error: error.message, debug: d };
  }
}"
}
